function createPremiumReportV4Pdf({ chart, metadata, presentation = {}, report, evidenceCatalog }) {
  if (report?.schemaVersion !== VERSION) throw new Error("Renderer v4 принимает только personal-report-v4.");
  if (!Array.isArray(evidenceCatalog?.items)) throw new Error("Renderer v4 требует versioned evidence catalog.");
  return new Promise((resolve,reject)=>{
    const doc=new PDFDocument({size:"A4",margin:0,bufferPages:true,autoFirstPage:false,info:{
      Title:`${presentation.displayName?`${presentation.displayName} - `:""}Ба-цзы + Цзы Вэй Доу Шу · Персональный разбор`,
      Author:"Тянь Мин",Subject:"Персональный отчёт Ба-цзы и Цзы Вэй Доу Шу",
      Keywords:`Тянь Мин, Ба-цзы, Цзы Вэй Доу Шу, персональный разбор, ${VERSION}`,
      Creator:"Тянь Мин Premium Report",Producer:"Тянь Мин / PDFKit",CreationDate:new Date(),ReportVersion:VERSION,
    }});
    const chunks=[];doc.on("data",value=>chunks.push(value));doc.on("error",reject);doc.on("end",()=>resolve(Buffer.concat(chunks)));
    try{
      const fonts=registerFonts(doc);
      const ctx={doc,fonts,chart,metadata,presentation,report,catalog:evidenceCatalog,byId:new Map(evidenceCatalog.items.map(value=>[value.id,value])),sections:[],tocPages:[],sectionTitle:"",appendix:false};
      cover(ctx);reserveContents(ctx);earlyBazi(ctx);earlyElements(ctx);earlyZiwei(ctx);timeMap(ctx);portrait(ctx);readingGuide(ctx);personality(ctx);strengths(ctx);growth(ctx);
      career(ctx);money(ctx);relationships(ctx);externalInternal(ctx);worldChapter(ctx);
      currentPeriod(ctx);years(ctx);transitions(ctx);matrix(ctx);scenarios(ctx);actionPlan(ctx);selfCheck(ctx);finalLine(ctx);
      baziBalance(ctx);palaceMap(ctx);timeAppendix(ctx);precision(ctx);methodology(ctx);
      renderContents(ctx);pageNumbers(ctx);doc.end();
    }catch(error){reject(error);}
  });
}

